const D = { expand: 1.035, spin: 0.03, energy: .6, speed: 1, density: .5, scale: 1, hue: 200, x: .5, y: .5, style: 'spectral-vortex', seed: 0, alpha: 100 };
const P = Object.assign({}, D, (window.state.P && window.state.P.__SLOT__) || {});
const S = window.state.__SLOT__ || (window.state.__SLOT__ = {});
const K = window.state.clk || { t:0, cps:.5, beat:0, bar:0, cyc:0, phase:0, pulse:0, swell:0, section:0, intensity:.6, fps:60 };
const A = window.state.audio || { bass:0, lowmid:0, mid:0, treble:0, rms:0, fft:[] };

// ---- ping-pong feedback buffers, cached on size (half-canvas per PROBE) ----
const BW = Math.min(560, Math.max(180, Math.round(width * 0.5)));
const BH = Math.max(120, Math.round(BW * height / width));
if (!S.g || S.key !== BW + 'x' + BH) {
  S.g = createGraphics(BW, BH); S.g.pixelDensity(1); S.g.colorMode(HSB, 360, 100, 100, 100);
  S.h = createGraphics(BW, BH); S.h.pixelDensity(1); S.h.colorMode(HSB, 360, 100, 100, 100);
  S.g.noStroke(); S.g.fill(P.hue, 55, 12); S.g.rect(0, 0, BW, BH);
  S.key = BW + 'x' + BH;
}
// deterministic per-seed offsets (inline hash, no p5 random)
if (S.seedUsed !== P.seed) {
  S.seedUsed = P.seed;
  const fr = i => { const s = Math.sin(i * 127.1 + P.seed * 311.7) * 43758.5453; return s - Math.floor(s); };
  S.hoff = fr(1) * 360; S.roff = fr(2) * 6.283; S.sideBias = 3 + Math.floor(fr(3) * 6); S.spokeBias = Math.floor(fr(4) * 5);
}

const g = S.g, h = S.h;
const cx = BW * 0.5, cy = BH * 0.5;
const mx = P.x * BW, my = P.y * BH;
const style = P.style;
const u = Math.min(BW, BH);
const TAU = 6.28318530718;

// dramaturgy: slow section-driven breathing + palette drift over minutes
const sec = K.section | 0;
const arc = 0.5 + 0.5 * Math.sin(K.t * 0.045 + sec);
const kick = K.pulse * 0.5 + A.bass * 0.9;
const glow = K.swell * 0.3 + A.rms * 0.8;

// per-frame feedback transform — this BUILDS the tunnel (continuous, never re-phases)
const zoom = P.expand + kick * 0.02 + arc * 0.006;              // >1 => spirals OUTWARD to the edges
const dir = (sec % 2) ? -1 : 1;
const rot = (P.spin * (0.7 + 0.5 * arc)) * dir + A.mid * 0.03 + Math.sin(K.t * 0.05) * 0.008;
const decay = 0.94 - P.energy * 0.06;                          // brightness multiply guard (0.88..0.94) => never washes to white

// motif palette / brightness (fresh content injected every frame)
const motH = (P.hue + S.hoff + K.t * 26 * P.speed + sec * 12) % 360;
const bri = 78 + P.energy * 22 + glow * 20;
const ringR = u * (0.20 + 0.16 * P.scale) * (1 + kick * 0.15);
const sides = S.sideBias + (style === 'spectral-vortex' ? 4 : 3);
const sw = Math.max(1.5, u * 0.012 * (0.6 + P.density));
const spin2 = K.t * 0.5 * P.speed + S.roff;
const nSpokes = Math.round(3 + P.density * 8 + S.spokeBias + A.treble * 6);

function ringDraw(gr, r, n, a0, wght) {
  gr.noFill(); gr.strokeWeight(wght);
  for (let i = 0; i < n; i++) {
    const a = a0 + i / n * TAU, b = a0 + (i + 1) / n * TAU;
    let hu, sa, bl;
    if (style === 'spectral-vortex') { hu = (motH + i / n * 200) % 360; sa = 90; bl = bri; }
    else if (style === 'oil-slick') { hu = (motH + i / n * 320 + 30 * Math.sin(a * 3)) % 360; sa = 55; bl = 52 + 38 * (0.5 + 0.5 * Math.sin(a * 4)); }
    else if (style === 'infrared') { const tf = 0.5 + 0.5 * Math.sin(a + spin2); hu = 8 + tf * 40; sa = 100 - tf * 45; bl = 55 + tf * 45; }
    else if (style === 'mono-strobe') { hu = 0; sa = 0; bl = bri; }
    else { hu = motH; sa = 82; bl = bri; }
    gr.stroke(hu, sa, bl, 100);
    gr.line(Math.cos(a) * r, Math.sin(a) * r, Math.cos(b) * r, Math.sin(b) * r);
  }
}
function discDraw(gr, r) {
  gr.noStroke();
  let dh, ds, db, da;
  if (style === 'infrared') { dh = 4; ds = 95; db = 45 + glow * 15; da = 42; }
  else if (style === 'mono-strobe') { dh = 0; ds = 0; db = 32; da = 42; }
  else if (style === 'oil-slick') { dh = (motH + 60) % 360; ds = 48; db = 30; da = 46; }
  else { dh = motH; ds = 85; db = 45 + glow * 20; da = 40; }
  gr.fill(dh, ds, db, da);
  gr.circle(0, 0, r * 2);
}

// ---- 1) feedback step: ambient fill (gap guard + luminance floor) then transformed copy ----
h.blendMode(BLEND);
h.push();
h.noStroke();
const ambH = (P.hue + S.hoff + K.t * 6 * P.speed + sec * 20) % 360;
h.fill(ambH, 45, 10 + arc * 5);
h.rect(0, 0, BW, BH);
h.pop();

h.push();
h.translate(cx, cy); h.rotate(rot); h.scale(zoom); h.translate(-cx, -cy);
h.tint(0, 0, decay * 100);
h.image(g, 0, 0, BW, BH);
h.noTint();
h.pop();

// ---- 2) inject a BOLD motif so the echo always has fresh content ----
h.push();
h.translate(mx, my);
if (style === 'neon-kaleido') {
  const KN = 6;
  for (let m = 0; m < KN; m++) {
    h.push();
    h.rotate(spin2 + m / KN * TAU);
    h.blendMode(ADD); discDraw(h, ringR * 0.5);
    h.blendMode(BLEND);
    ringDraw(h, ringR, Math.max(7, sides), 0, sw);
    h.stroke(motH, 80, bri, 90); h.strokeWeight(sw * 0.7);
    h.line(0, 0, ringR * 1.5, 0);
    h.pop();
  }
  h.blendMode(BLEND);
} else {
  discDraw(h, ringR * 0.9);
  ringDraw(h, ringR, Math.max(7, sides), spin2, sw);
  h.strokeWeight(sw * 0.6);
  for (let k = 0; k < nSpokes; k++) {
    const a = spin2 + k / nSpokes * TAU;
    const sh = style === 'mono-strobe' ? 0 : (motH + k * 12) % 360;
    const ss = style === 'mono-strobe' ? 0 : (style === 'infrared' ? 90 : 70);
    const sb = style === 'infrared' ? 92 : bri;
    h.stroke(sh, ss, sb, 70);
    h.line(Math.cos(a) * ringR * 0.3, Math.sin(a) * ringR * 0.3, Math.cos(a) * ringR * 1.35, Math.sin(a) * ringR * 1.35);
  }
}
h.pop();

// ---- 3) swap + blit to full canvas ----
S.g = h; S.h = g;
push();
if (P.alpha < 100) tint(0, 0, 100, P.alpha);
image(S.g, 0, 0, width, height);
pop();
